// 发行参数严格固定，业务条款仅由本域原政策报价派生；公共消息沿具名事实可见性。
#include "supply_policy_boundary.hpp"
#include "supply_policy_codec.hpp"
#include "../economic_payload_guard.hpp"
#include "../views/local_economy_view.hpp"
namespace hanmo::resident {
Outcome<IssueEconomicSupplyPolicyCommand> decode_issue_economic_supply_policy(const BoundaryValue& input){auto unique=validate_economic_payload_fields(input);if(!unique.ok)return {false,{},unique.error};try{boundary::fields(input,{"authority","registration_fact_id","author_policy_id"},{},"/political_issue_supply_policy");IssueEconomicSupplyPolicyCommand out;dynamic_economy_codec::decode(boundary::field(input,"authority","/political_issue_supply_policy"),out.authority,"/authority");out.registration_fact_id=boundary::get_string(input,"registration_fact_id","/political_issue_supply_policy");out.author_policy_id=boundary::get_string(input,"author_policy_id","/political_issue_supply_policy");if(out.registration_fact_id.empty()||out.author_policy_id.empty())boundary::fail("InvalidEconomicSupplyPolicyCommand","/political_issue_supply_policy");return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_issue_economic_supply_policy(const IssueEconomicSupplyPolicyCommand& c){return boundary::obj({{"authority",dynamic_economy_codec::encode(c.authority)},{"registration_fact_id",BoundaryValue{c.registration_fact_id}},{"author_policy_id",BoundaryValue{c.author_policy_id}}});}
BoundaryValue encode_economic_supply_policy_quote(const EconomicSupplyPolicyQuote& q){using V=BoundaryValue;LocalEconomyPage page;page.identity=q.source_identity;page.observer_actor_id=q.actor_id;auto base=encode_local_economy_page(page);return boundary::obj({{"identity",*base.find("identity")},{"actor_id",V{q.actor_id}},{"command_kind",V{"political_issue_supply_policy"}},{"params",encode_issue_economic_supply_policy(q.command)},{"policy",dynamic_economy_codec::encode(q.proposed.policy)},{"target_amount",V{q.proposed.target_amount}},{"earliest_effective_tick",V{q.proposed.earliest_effective_tick}},{"through_tick",V{q.proposed.through_tick}},{"maximum_contract_commitment",V{q.proposed.maximum_contract_commitment}},{"status",V{"pending_approval"}}});}
BoundaryValue encode_economic_supply_policy_receipt(const EconomicSupplyPolicyReceipt& r){using V=BoundaryValue;return boundary::obj({{"policy_fact_id",V{r.policy_fact_id}},{"registration_fact_id",V{r.registration_fact_id}},{"original_source_key",V{r.original_source_key}}});}
// 原DynamicResultRead消费此口即可接公开报告；不把新policy ID塞回旧作者知情表。
Outcome<std::optional<DynamicFactView>> economic_supply_policy_dynamic_fact(const EconomicSupplyPolicyContext& x,const StableId& id){auto valid=validate_economic_supply_policies(x);if(!valid.ok)return {false,{},valid.error};DynamicFactView out;out.id=id;out.rule_version="economic_supply_policies_v1";if(const auto* r=x.ledger.state.policies.find(id)){out.kind=economic_supply_policy_issue_kind;out.tick=r->issued_tick;out.subject_id=r->policy.organization_id;out.participants={{{SubjectKind::actor,r->authority.actor_id},"requester"},{{SubjectKind::organization,r->policy.organization_id},"principal"}};out.cause_fact_ids={r->registration_fact_id,r->original_source_fact_id};out.outcome="supply_policy_pending_approval";return {true,std::move(out),{}};}if(const auto* o=x.ledger.state.observations.find(id)){out.kind=economic_supply_observation_kind;out.tick=o->observation.tick;out.subject_id=o->observation.observation.organization_id;out.participants={{{SubjectKind::organization,out.subject_id},"principal"}};out.supply=o->observation.observation;out.publicly_visible=o->observation.publicly_visible;out.cause_fact_ids={o->policy_fact_id};out.outcome="supply_observed";return {true,std::move(out),{}};}return {true,{}, {}};}
}
